(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const s = window.__toolboxStore;
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const out = {};

  // ① 建一个卍解项目
  const nameInput = document.querySelector('.tb-card .tb-input');
  out.panelOpen = !!nameInput;
  if (!nameInput) return JSON.stringify(out);
  setV(nameInput, '卍解测试·超声波避障');
  [...document.querySelectorAll('.tb-diff-opt')].find((b) => b.textContent.includes('卍解'))?.click();
  await sleep(400);
  out.picked = document.querySelector('.tb-diff-opt-on')?.textContent.trim() || null;
  [...document.querySelectorAll('.tb-btn-primary')].find((b) => b.textContent.includes('创建'))?.click();
  await sleep(3800);
  out.openedTitle = document.querySelector('.pj-title')?.textContent || null;
  out.diffBadge = document.querySelector('.pj-diff')?.textContent || null;

  // ② 详情页出现「程序代码」区（始解作品没有这块）
  out.codePanel = !!document.querySelector('.pc-wrap');
  out.codeHead = document.querySelector('.pc-head h2')?.textContent || null;
  out.emptyHint = (document.querySelector('.pc-empty')?.textContent || '').trim().slice(0, 26) || null;

  // ③ 贴一段代码
  [...document.querySelectorAll('.pc-btn')].find((b) => b.textContent.includes('直接贴代码'))?.click();
  await sleep(700);
  const inputs = [...document.querySelectorAll('.pc-input')];
  out.inputCount = inputs.length;
  if (inputs.length < 2) return JSON.stringify(out);
  setV(inputs[0], 'avoid.ino');
  setV(inputs[1], '超声波避障主程序');
  setV(document.querySelector('.pc-textarea'), 'void setup() {\n  pinMode(9, OUTPUT);\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  digitalWrite(9, HIGH);\n  delay(500);\n  digitalWrite(9, LOW);\n  delay(500);\n}\n');
  await sleep(300);
  [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.includes('放进作品'))?.click();
  await sleep(2500);
  out.msg = document.querySelector('.pc-msg')?.textContent || null;
  out.fileItems = [...document.querySelectorAll('.pc-item-name')].map((e) => e.textContent);
  out.fileMeta = [...document.querySelectorAll('.pc-item-meta')].map((e) => e.textContent);
  out.codeShown = (document.querySelector('.pc-code')?.textContent || '').includes('pinMode(9, OUTPUT)');

  // ④ 存储层确认
  const projects = await s.listProjects();
  const p = projects.find((x) => x.name.includes('卍解测试'));
  out.projectDifficulty = p?.difficulty;
  out.projectCodeCount = p?.codeCount;
  out.cardBadge = null;
  const files = await s.listCodeFiles(p.id);
  out.stored = files.map((f) => ({ name: f.name, lang: f.language, lines: f.content.split('\n').length, note: f.note }));
  out.projectId = p.id;
  return JSON.stringify(out);
})()
